mapper.select:
WITH T0 AS ( SELECT DISTINCT SDELIVERYD.STOFCY_0 AS Site, SDELIVERY.BPCORD_0 AS CustomerCode, BPCUSTOMER.BPCSHO_0 AS CustomerName, SDELIVERYD.SDHNUM_0 AS DeliveryNO, SDELIVERYD.SDDLIN_0 AS DeliveryLine, SDELIVERYD.SOHNUM_0 AS OrderNO, SDELIVERYD.SOPLIN_0 AS OrderLine, SDELIVERYD.ITMREF_0 AS PN FROM EXPLOIT.SDELIVERYD SDELIVERYD LEFT JOIN EXPLOIT.SDELIVERY SDELIVERY ON SDELIVERYD.SDHNUM_0 = SDELIVERY.SDHNUM_0 INNER JOIN EXPLOIT.SORDERQ SORDERQ ON SORDERQ.SOHNUM_0 = SDELIVERYD.SOHNUM_0 AND SORDERQ.SOPLIN_0 = SDELIVERYD.SOPLIN_0 INNER JOIN EXPLOIT.SORDER SORDER ON SORDER.SOHNUM_0 = SDELIVERYD.SOHNUM_0 INNER JOIN EXPLOIT.COMPANY ON COMPANY.MAIFCY_0 = SDELIVERY.SALFCY_0 INNER JOIN EXPLOIT.BPCUSTOMER BPCUSTOMER ON SDELIVERY.BPCORD_0 = BPCUSTOMER.BPCNUM_0 WHERE 1=1 AND (SDELIVERY.SHIDAT_0 BETWEEN CONVERT(DATETIME, #{DateFrom} ,120) AND CONVERT(DATETIME, #{DateTo} ,120))
AND SDELIVERY.BPCORD_0 = #{CustomerCode}
AND SORDER.SALFCY_0 IN ('ZHU','HKG','YSH')
AND SORDER.SALFCY_0 = #{Site}
)
SELECT COUNT(1) FROM T0

WITH T0 AS ( SELECT DISTINCT ROW_NUMBER() OVER (ORDER BY SDELIVERYD.SHIDAT_0 ASC) AS ItemNO, SDELIVERYD.STOFCY_0 AS Site, SDELIVERY.BPCORD_0 AS CustomerCode, BPCUSTOMER.BPCSHO_0 AS CustomerName, SDELIVERYD.SDHNUM_0 AS DeliveryNO, SDELIVERYD.SDDLIN_0 AS DeliveryLine, (CASE WHEN SORDERQ.YSOQ_STA_0 =1 THEN SORDER.SOHTYP_0 + '-Methods' WHEN SORDERQ.YSOQ_STA_0 =2 THEN SORDER.SOHTYP_0 + '-InteralProd' WHEN SORDERQ.YSOQ_STA_0 =3 THEN SORDER.SOHTYP_0 + '-ExternalProd' WHEN SORDERQ.YSOQ_STA_0 =4 THEN SORDER.SOHTYP_0 + '-Design' WHEN SORDERQ.YSOQ_STA_0 =5 THEN SORDER.SOHTYP_0 + '-Stock' WHEN SORDERQ.YSOQ_STA_0 =6 THEN SORDER.SOHTYP_0 + '-Trading' WHEN SORDERQ.YSOQ_STA_0 =7 THEN SORDER.SOHTYP_0 + '-Services' WHEN SORDERQ.YSOQ_STA_0 =8 THEN SORDER.SOHTYP_0 + '-SalesAdmin' ELSE SORDER.SOHTYP_0 + '-UNK' END) AS OrderType, SORDERQ.SOHNUM_0 AS OrderNO, SORDERQ.SOPLIN_0 AS OrderLine, SORDERQ.YSOH_PJT_0 AS ProjectNO, SDELIVERYD.ITMREF_0 AS PN, RTRIM(SDELIVERYD.ITMDES1_0 + ' ' + SDELIVERYD.ITMDES2_0) AS Description, SDELIVERYD.QTY_0 AS Qty, SDELIVERYD.NETPRI_0 AS NetPrice, SDELIVERYD.NETPRIATI_0 AS NetPriceWithTax, SDELIVERYD.QTY_0*SDELIVERYD.NETPRI_0 AS TotalAmount, SDELIVERYD.QTY_0*SDELIVERYD.NETPRIATI_0 AS TotalAmountWithTax, IIF(SDELIVERY.DLVATI_0 = 0, 0, SDELIVERYD.QTY_0*SDELIVERYD.NETPRI_0*(SDELIVERY.DLVATIL_0/SDELIVERY.DLVATI_0)) AS TotalLocalAmount, IIF(SDELIVERY.DLVATI_0 = 0, 0, SDELIVERYD.QTY_0*SDELIVERYD.NETPRIATI_0*(SDELIVERY.DLVATIL_0/SDELIVERY.DLVATI_0)) AS TotalLocalAmountWithTax, SDELIVERY.CUR_0 AS Currency, COMPANY.ACCCUR_0 AS LocalCurrency, SDELIVERYD.SHIDAT_0 AS DeliveryDate, SORDERQ.YSOQ_DLIVP_0 AS OrderPlanedDate FROM EXPLOIT.SDELIVERYD SDELIVERYD LEFT JOIN EXPLOIT.SDELIVERY SDELIVERY ON SDELIVERYD.SDHNUM_0 = SDELIVERY.SDHNUM_0 INNER JOIN EXPLOIT.SORDERQ SORDERQ ON SORDERQ.SOHNUM_0 = SDELIVERYD.SOHNUM_0 AND SORDERQ.SOPLIN_0 = SDELIVERYD.SOPLIN_0 INNER JOIN EXPLOIT.SORDER SORDER ON SORDER.SOHNUM_0 = SDELIVERYD.SOHNUM_0 INNER JOIN EXPLOIT.COMPANY ON COMPANY.MAIFCY_0 = SDELIVERY.SALFCY_0 INNER JOIN EXPLOIT.BPCUSTOMER BPCUSTOMER ON SDELIVERY.BPCORD_0 = BPCUSTOMER.BPCNUM_0 WHERE 1=1 AND (SDELIVERY.SHIDAT_0 BETWEEN CONVERT(DATETIME, #{DateFrom} ,120) AND CONVERT(DATETIME, #{DateTo} ,120))
AND SDELIVERY.BPCORD_0 = #{CustomerCode}
AND SORDER.SALFCY_0 IN ('ZHU','HKG','YSH')
AND SORDER.SALFCY_0 = #{Site}
ORDER BY ItemNO ASC OFFSET #{Offset} ROWS FETCH NEXT #{Limit} ROWS ONLY )
SELECT T0.*, DATEDIFF(day, T0.OrderPlanedDate, T0.DeliveryDate) AS DaysDelay FROM T0
